from fractions import Fraction
from math import gcd


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _q(v):
    if _is_int(v):
        return Fraction(v)
    if isinstance(v, str) and ('.' not in v) and ('e' not in v) and ('E' not in v):
        try:
            return Fraction(v)
        except (ValueError, ZeroDivisionError):
            return None
    return None


def _tree_root(leaves):
    level = list(leaves)
    if not level:
        return 0
    while len(level) > 1:
        nxt = []
        i = 0
        while i < len(level):
            if i + 1 < len(level):
                nxt.append(level[i] + level[i + 1])
            else:
                nxt.append(level[i])
            i += 2
        level = nxt
    return level[0]


def _invariant(case):
    n = case.get('n')
    s = case.get('step')
    xs = case.get('samples')
    if not (_is_int(n) and n > 0 and _is_int(s)):
        return False
    if not (isinstance(xs, list) and len(xs) == n):
        return False
    for x in xs:
        if not _is_int(x):
            return False
    lo = _q(case.get('lo'))
    hi = _q(case.get('hi'))
    if lo is None or hi is None or not (lo < hi):
        return False
    init = case.get('init')
    if not (_is_int(init) and init in (0, 1)):
        return False
    if gcd(s % n, n) != 1:
        return False
    order = []
    seen = set()
    p = 0
    for _ in range(n):
        if p in seen:
            return False
        seen.add(p)
        order.append(p)
        p = (p + s) % n
    if p != 0 or len(seen) != n:
        return False
    state = init
    states = []
    toggles = 0
    tv = Fraction(0)
    prev = None
    for idx in order:
        x = Fraction(xs[idx])
        if prev is not None:
            tv += abs(x - prev)
        prev = x
        if state == 0 and x >= hi:
            state = 1
            toggles += 1
        elif state == 1 and x <= lo:
            state = 0
            toggles += 1
        states.append(state)
    runs = []
    start = 0
    for i in range(1, n + 1):
        if i == n or states[i] != states[start]:
            runs.append((start, i, states[start]))
            start = i
    if runs[0][0] != 0 or runs[-1][1] != n:
        return False
    for j in range(1, len(runs)):
        if runs[j][0] != runs[j - 1][1] or runs[j][2] == runs[j - 1][2]:
            return False
    if _tree_root([e - b for (b, e, _st) in runs]) != n:
        return False
    on_runs = sum(e - b for (b, e, st) in runs if st == 1)
    if on_runs != sum(states):
        return False
    if not (len(runs) - 1 <= toggles <= len(runs)):
        return False
    if toggles > 0 and Fraction(toggles - 1) * (hi - lo) > tv:
        return False
    ct = case.get('claimed_toggles')
    if ct is not None and not (_is_int(ct) and ct == toggles):
        return False
    cr = case.get('claimed_runs')
    if cr is not None and not (_is_int(cr) and cr == len(runs)):
        return False
    con = case.get('claimed_on')
    if con is not None and not (_is_int(con) and con == on_runs):
        return False
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get('expected')
    if not isinstance(exp, bool):
        return False
    return _invariant(case) == exp

from fractions import Fraction
from math import gcd

def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def _frac(pair):
    if not isinstance(pair, list) or len(pair) != 2:
        return None
    a, b = pair
    if not _is_int(a) or not _is_int(b) or b <= 0:
        return None
    return Fraction(a, b)

def _tree_checksum(seq):
    level = list(seq)
    if not level:
        return 0
    while len(level) > 1:
        nxt = []
        i = 0
        while i + 1 < len(level):
            nxt.append(level[i] + 3 * level[i + 1])
            i += 2
        if i < len(level):
            nxt.append(level[i])
        level = nxt
    return level[0]

def check_case(case):
    if not isinstance(case, dict):
        return False
    n = case.get("n")
    stride = case.get("stride")
    levels = case.get("levels")
    claim = case.get("claim")
    if not _is_int(n) or n < 1 or not _is_int(stride):
        return False
    if stride < 1 or stride > n or gcd(stride, n) != 1:
        return False
    if not isinstance(levels, list) or len(levels) != n:
        return False
    xs = []
    for pair in levels:
        f = _frac(pair)
        if f is None:
            return False
        xs.append(f)
    lo = _frac(case.get("lo"))
    hi = _frac(case.get("hi"))
    if lo is None or hi is None or not lo < hi:
        return False
    order = [(i * stride) % n for i in range(n)]
    if sorted(order) != list(range(n)):
        return False
    state = 0
    flips = 0
    for idx in order:
        x = xs[idx]
        if state == 0 and x >= hi:
            state = 1
            flips += 1
        elif state == 1 and x <= lo:
            state = 0
            flips += 1
    high_count = 0
    low_count = 0
    bits = []
    for x in xs:
        if x >= hi:
            high_count += 1
            bits.append(1)
        elif x <= lo:
            low_count += 1
            bits.append(1)
        else:
            bits.append(0)
    if flips > high_count + low_count:
        return False
    if flips > 2 * min(high_count, low_count) + 1:
        return False
    runs = []
    i = 0
    while i < n:
        j = i
        while j < n and bits[j] == bits[i]:
            j += 1
        runs.append([i, j - i, bits[i]])
        i = j
    if not isinstance(claim, dict):
        return False
    claimed_runs = claim.get("intervals")
    claimed_sum = claim.get("checksum")
    claimed_flips = claim.get("flips")
    if not isinstance(claimed_runs, list) or not _is_int(claimed_sum) or not _is_int(claimed_flips):
        return False
    if claimed_flips != flips:
        return False
    rebuilt = []
    pos = 0
    prev_bit = -1
    for run in claimed_runs:
        if not isinstance(run, list) or len(run) != 3:
            return False
        start, length, bit = run
        if not _is_int(start) or not _is_int(length) or not _is_int(bit):
            return False
        if start != pos or length < 1 or bit not in (0, 1) or bit == prev_bit:
            return False
        rebuilt.extend([bit] * length)
        pos += length
        prev_bit = bit
    if pos != n or rebuilt != bits:
        return False
    if claimed_runs != runs:
        return False
    if claimed_sum != _tree_checksum(bits):
        return False
    if _tree_checksum(rebuilt) != _tree_checksum(bits):
        return False
    canon = Fraction(0)
    for i in range(n):
        canon += (i + 1) * xs[i]
    trav = Fraction(0)
    for idx in order:
        trav += (idx + 1) * xs[idx]
    return canon == trav

from fractions import Fraction
from math import gcd


def channel_span(stream):
    first = {}
    last = {}
    for pos in range(len(stream)):
        ch = stream[pos]
        if ch not in first:
            first[ch] = pos
        last[ch] = pos
    return first, last


def c1p_holds(stream):
    first, last = channel_span(stream)
    good = True
    for ch in first:
        for pos in range(first[ch], last[ch] + 1):
            if stream[pos] != ch:
                good = False
    return good


def partition_blocks(stream):
    first, last = channel_span(stream)
    spans = sorted((first[ch], last[ch], ch) for ch in first)
    out = []
    for lo, hi, ch in spans:
        if out and lo <= out[-1][1]:
            if hi > out[-1][1]:
                out[-1] = (out[-1][0], hi)
        else:
            out.append((lo, hi))
    return out


def fold_digits(vals, mul, mod):
    acc = 0
    for v in vals:
        acc = (acc * mul + v) % mod
    return acc


def tree_root(stream, mod, mul, arity):
    level = []
    for lo, hi in partition_blocks(stream):
        level.append(fold_digits([(pos + 1) * (stream[pos] + 1) for pos in range(lo, hi + 1)], mul, mod))
    if not level:
        return 0
    while len(level) > 1:
        nxt = []
        for i in range(0, len(level), arity):
            chunk = level[i:i + arity]
            if len(chunk) == 1:
                nxt.append(chunk[0])
            else:
                tag = 1 if chunk == sorted(chunk) else 2
                nxt.append(fold_digits([tag] + chunk, mul, mod))
        level = nxt
    return level[0]


def cycle_and_distinct(m, n):
    cycle = m * n // gcd(m, n)
    seen = set()
    for t in range(cycle):
        seen.add((t % m, t % n))
    return cycle, len(seen)


def coprime_handoffs(nb, cycle):
    cnt = 0
    for b in range(1, nb + 1):
        for t in range(1, cycle + 1):
            if gcd(b, t) == 1:
                cnt += 1
    return cnt


def valve_trace(deltas, deadband, friction):
    trace = []
    acc = 0
    hold = deadband + friction
    for d in deltas:
        acc += d
        if abs(acc) > hold:
            trace.append(1)
            acc = 0
        else:
            trace.append(0)
    return trace


def check_case(case):
    stream = case["stream"]
    mod = case["modulus"]
    mul = case["mul"]
    arity = case["arity"]
    m = case["grid"][0]
    n = case["grid"][1]
    deltas = case["pressure"]
    deadband = case["deadband"]
    friction = case["friction"]

    blocks = partition_blocks(stream)
    if not blocks:
        return bool(False) == bool(case["expect"])

    part_ok = c1p_holds(stream) and len(blocks) == case["blocks"]
    if blocks[0][0] != 0 or blocks[-1][1] != len(stream) - 1:
        part_ok = False
    for i in range(len(blocks) - 1):
        if blocks[i][1] + 1 != blocks[i + 1][0]:
            part_ok = False

    root_ok = tree_root(stream, mod, mul, arity) == case["root"]

    cycle, distinct = cycle_and_distinct(m, n)
    single = distinct == m * n
    cycle_ok = single == bool(case["single_cycle"]) and cycle * gcd(m, n) == m * n

    hoff_ok = coprime_handoffs(len(blocks), cycle) == case["handoffs"]

    gain = Fraction(deadband, deadband + friction)
    valve_ok = valve_trace(deltas, deadband, friction) == list(case["trace"])
    valve_ok = valve_ok and gain < 1 and gain > 0
    bound_ok = len(valve_trace(deltas, deadband, friction)) == len(deltas)

    computed = part_ok and root_ok and cycle_ok and hoff_ok and valve_ok and bound_ok
    return bool(computed) == bool(case["expect"])

