from math import gcd


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _egcd(a, b):
    x0, y0, x1, y1 = 1, 0, 0, 1
    while b != 0:
        q = a // b
        a, b = b, a - q * b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return a, x0, y0


def _merge(a, m, b, n):
    g = gcd(m, n)
    if (b - a) % g != 0:
        return None
    mp = m // g
    nq = n // g
    gg, inv, unused = _egcd(mp % nq, nq)
    if gg != 1:
        return None
    t = (((b - a) // g) * inv) % nq
    lcm = m * nq
    return ((a + m * t) % lcm, lcm)


def _predict(case):
