    if k == 0 or k != len(rems):
        return False
    for v in moduli:
        if not _is_int(v) or v <= 0:
            return False
    for v in rems:
        if not _is_int(v):
            return False
    claim_x = case.get('claim_x')
    if claim_x is not None and not _is_int(claim_x):
        return False
    claim_sc = case.get('claim_single_cycle')
    if not isinstance(claim_sc, bool):
        return False
