    prod = 1
    for m in moduli:
        big_l = big_l * m // gcd(big_l, m)
        prod = prod * m
    if big_l > 100000:
        return False
    sols = [x for x in range(big_l) if all(x % moduli[i] == r[i] for i in range(k))]
    pairwise = all((r[i] - r[j]) % gcd(moduli[i], moduli[j]) == 0 for i in range(k) for j in range(i + 1, k))
    coprime = all(gcd(moduli[i], moduli[j]) == 1 for i in range(k) for j in range(i + 1, k))
    acc = (r[0], moduli[0])
    for i in range(1, k):
        if acc is None:
            break
        acc = _merge(acc[0], acc[1], r[i], moduli[i])
    merged = None if acc is None else acc[0]
    consistent = len(sols) <= 1 and pairwise == (len(sols) == 1) and (prod == big_l) == coprime
    if consistent and pairwise:
        consistent = acc is not None and merged == sols[0] and acc[1] == big_l
    if consistent and not pairwise:
        consistent = acc is None
    if not consistent:
        return False
    return pairwise and claim_x == merged and claim_sc == (prod == big_l)


def check_case(case):
