def _rat(v):
    if not isinstance(v, list) or len(v) != 2:
        return None
    a = v[0]
    b = v[1]
    if not _is_int(a) or not _is_int(b) or b <= 0:
        return None
    return Fraction(a, b)

def _fold(vals):
    if len(vals) == 0:
        return 0
    if len(vals) == 1:
        return vals[0]
    m = len(vals) // 2
    return _fold(vals[:m]) + 3 * _fold(vals[m:])

def _predict(case):
    n = case.get("n")
    stride = case.get("stride")
    init = case.get("init")
    levels = case.get("levels")
    if not _is_int(n) or n < 1:
        return False
    if not _is_int(stride) or not _is_int(init) or init not in (0, 1):
        return False
    if not isinstance(levels, list) or len(levels) != n:
        return False
    xs = []
    for v in levels:
        r = _rat(v)
        if r is None:
            return False
        xs.append(r)
    lo = _rat(case.get("lo"))
    hi = _rat(case.get("hi"))
    if lo is None or hi is None or not lo < hi:
        return False
    if gcd(stride % n, n) != 1:
        return False
    order = [(k * stride) % n for k in range(n)]
    if sorted(order) != list(range(n)):
        return False
    q = init
    out = []
    flips = 0
    for p in order:
        x = xs[p]
        if x >= hi:
            nq = 1
        elif x <= lo:
            nq = 0
        else:
            nq = q
        if nq != q:
            flips += 1
        q = nq
        out.append(q)
    runs = []
    start = 0
    for k in range(1, n):
        if out[k] != out[k - 1]:
            runs.append([start, k - start, out[start]])
            start = k
    runs.append([start, n - start, out[start]])
    R = len(runs)
    delta = 1 if out[0] != init else 0
    if flips != R - 1 + delta:
        return False
    H = sum(1 for x in xs if x >= hi)
    L = sum(1 for x in xs if x <= lo)
    if flips > H + L or flips > 2 * min(H, L) + 1:
        return False
    tv = Fraction(0)
    for k in range(1, n):
        d = xs[order[k]] - xs[order[k - 1]]
        tv += d if d >= 0 else -d
    if (flips - 1) * (hi - lo) > tv:
        return False
    on_count = sum(out)
    moment = Fraction(0)
    for p in range(n):
        moment += (p + 1) * xs[p]
    leaves = [2 * r[1] + r[2] for r in runs]
    root = _fold(leaves)
    claim = case.get("claim")
    if not isinstance(claim, dict):
        return False
    ci = claim.get("intervals")
    if not isinstance(ci, list) or len(ci) == 0:
        return False
    canon = []
    for iv in ci:
        if not isinstance(iv, list) or len(iv) != 3:
            return False
        a = iv[0]
        b = iv[1]
        c = iv[2]
        if not _is_int(a) or not _is_int(b) or not _is_int(c):
            return False
        if b < 1 or c not in (0, 1):
            return False
        canon.append([a, b, c])
    if canon != runs:
        return False
    cf = claim.get("flips")
    if not _is_int(cf) or cf != flips:
        return False
    co = claim.get("on")
    if not _is_int(co) or co != on_count:
        return False
    cc = claim.get("checksum")
    if not _is_int(cc) or cc != root:
        return False
    cm = _rat(claim.get("moment"))
    if cm is None or cm != moment:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get("expected")
    if not isinstance(exp, bool):
        return False
    return _predict(case) == exp

