def _runs(states):
    out = []
    if len(states) == 0:
        return out
    start = 0
    cur = states[0]
    t = 1
    while t < len(states):
        if states[t] != cur:
            out.append([start, t - start, cur])
            start = t
            cur = states[t]
        t = t + 1
    out.append([start, len(states) - start, cur])
    return out

def _seal(lengths, p):
    nodes = []
    for i in range(len(lengths)):
        nodes.append(((i + 1) * (lengths[i] + 1)) % p)
    while len(nodes) > 1:
        nxt = []
        j = 0
        while j + 1 < len(nodes):
            left = nodes[j]
            right = nodes[j + 1]
            tag = 1 if left <= right else 2
            nxt.append((left + 3 * right + tag) % p)
            j = j + 2
        if j < len(nodes):
            nxt.append(nodes[j])
        nodes = nxt
    return nodes[0]

