            tv = 0
            for i in range(len(stream) - 1):
                d = stream[i + 1] - stream[i]
                if d < 0:
                    d = -d
                tv = tv + d
            init_flip = 0
            if states[0] == 1:
                init_flip = 1
            if claim.get('intervals') != runs_list:
                pred = False
            if claim.get('runs') != runs:
                pred = False
            if claim.get('flips') != flips:
                pred = False
            if claim.get('on_count') != on_count:
                pred = False
            if claim.get('on_runs') != on_runs:
                pred = False
            if claim.get('checksum') != seal:
                pred = False
            if flips != runs - 1 + init_flip:
                pred = False
            if on_runs != on_count:
                pred = False
            if flips > hcount + lcount:
                pred = False
            if flips > 2 * min(hcount, lcount) + 1:
                pred = False
