                if (flips - 1) * (hi - lo) > tv:
                    pred = False
            denom = damp[0] + damp[1]
            if denom < 1:
                pred = False
            if gain[1] < 1:
                pred = False
            if denom > 0 and gain[1] > 0:
                g = Fraction(damp[0], denom)
                if not (0 < g and g < 1):
                    pred = False
                if Fraction(gain[0], gain[1]) != g:
                    pred = False
    return pred == expected

from fractions import Fraction
from math import gcd

def as_int(value):
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    raise ValueError

def as_q(value):
    if isinstance(value, int) and not isinstance(value, bool):
        return Fraction(value, 1)
    if isinstance(value, list) and len(value) == 2:
        numerator = as_int(value[0])
        denominator = as_int(value[1])
        if denominator == 0:
            raise ValueError
        return Fraction(numerator, denominator)
    raise ValueError

def predict(case):
    raw_signal = case['signal']
    if not isinstance(raw_signal, list) or len(raw_signal) == 0:
        return False
    signal = [as_int(value) for value in raw_signal]
    n = len(signal)
    low = as_q(case['low'])
    high = as_q(case['high'])
    if not low < high:
        return False
    initial = as_int(case['initial'])
    if initial not in [0, 1]:
        return False
    stride = as_int(case['stride'])
    modulus = as_int(case['modulus'])
    if modulus <= 1:
        return False
    root = as_int(case['root'])
    if root < 0 or root >= modulus:
        return False
    max_intervals = as_int(case['max_intervals'])
    if max_intervals < 0:
        return False
    raw_states = case['states']
    if not isinstance(raw_states, list) or len(raw_states) != n:
        return False
    states = [as_int(value) for value in raw_states]
    if any(value not in [0, 1] for value in states):
        return False
    raw_intervals = case['intervals']
    if not isinstance(raw_intervals, list):
        return False
    intervals = []
    for item in raw_intervals:
        if not isinstance(item, list) or len(item) != 3:
            return False
        intervals.append([as_int(item[0]), as_int(item[1]), as_int(item[2])])
    if gcd(stride % n, n) != 1:
        return False
    order = [(t * stride) % n for t in range(n)]
    if sorted(order) != list(range(n)):
        return False
    rank = [0] * n
    for t in range(n):
        rank[order[t]] = t
    state = initial
    rebuilt = []
    for value in signal:
        exact_value = Fraction(value, 1)
        if state == 0:
            if exact_value >= high:
                state = 1
        else:
            if exact_value <= low:
                state = 0
        rebuilt.append(state)
    if states != rebuilt:
        return False
    runs = []
    start = 0
    for i in range(1, n + 1):
        if i == n or rebuilt[i] != rebuilt[start]:
            runs.append([start, i - 1, rebuilt[start]])
            start = i
    if intervals != runs:
        return False
    if len(runs) > max_intervals:
        return False
    toggles = sum(1 for i in range(1, n) if rebuilt[i] != rebuilt[i - 1])
    total_variation = Fraction(0, 1)
    for i in range(1, n):
        total_variation += Fraction(abs(signal[i] - signal[i - 1]), 1)
    if toggles > 0:
        required_variation = Fraction(toggles - 1, 1) * (high - low)
        if required_variation > total_variation:
            return False
    level = []
    for run in runs:
        first, last, label = run
        length = last - first + 1
        moment = 0
        for i in range(first, last + 1):
            moment += (rank[i] + 1) * signal[i]
        leaf = (first + 1) + 3 * length + 5 * label + 7 * moment
        level.append(leaf % modulus)
    while len(level) > 1:
        folded = []
        for i in range(0, len(level) - 1, 2):
            folded.append((level[i] + level[i + 1]) % modulus)
        if len(level) % 2 == 1:
            folded.append(level[-1])
        level = folded
    if root != level[0]:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    expected = case.get('expected')
    if not isinstance(expected, bool):
        return False
    try:
        prediction = predict(case)
    except (KeyError, TypeError, ValueError, IndexError, ZeroDivisionError):
        prediction = False
    return bool(prediction == expected)

