def _int(v):
    if isinstance(v, bool) or not isinstance(v, int):
        return None
    return v

def _frac(p):
    if not isinstance(p, list) or len(p) != 2:
        return None
    a = _int(p[0])
    b = _int(p[1])
    if a is None or b is None or b == 0:
        return None
    return Fraction(a, b)

def _runs(bits):
    runs = []
    i = 0
    n = len(bits)
    while i < n:
        j = i + 1
        while j < n and bits[j] == bits[i]:
            j += 1
        runs.append([i, j - i, bits[i]])
        i = j
    return runs

def _tree(leaves):
    if len(leaves) == 0:
        return None
    layer = list(leaves)
    while len(layer) > 1:
        nxt = []
        i = 0
        m = len(layer)
        while i < m:
            if i + 1 < m:
                nxt.append(layer[i] + layer[i + 1])
            else:
                nxt.append(layer[i])
            i += 2
        layer = nxt
    return layer[0]

def _predict(case):
    if not isinstance(case, dict):
        return False
    n = _int(case.get("n"))
    stride = _int(case.get("stride"))
    lo = _frac(case.get("lo"))
    hi = _frac(case.get("hi"))
    levels = case.get("levels")
    claim = case.get("claim")
    if n is None or stride is None or lo is None or hi is None:
        return False
    if n < 1 or not (lo < hi) or gcd(stride, n) != 1:
        return False
    if not isinstance(levels, list) or len(levels) != n:
        return False
    xs = []
    for row in levels:
        x = _frac(row)
        if x is None:
            return False
        xs.append(x)
