        return False
    checksum = _int(claim.get("checksum"))
    flips_c = _int(claim.get("flips"))
    intervals = claim.get("intervals")
    if checksum is None or flips_c is None or not isinstance(intervals, list):
        return False
    bits = []
    for x in xs:
        bits.append(1 if (x <= lo or x >= hi) else 0)
    runs = _runs(bits)
    if len(intervals) != len(runs):
        return False
    leaves = []
    on_len = 0
    for k in range(len(runs)):
        got = intervals[k]
        if not isinstance(got, list) or len(got) != 3:
            return False
        a = _int(got[0])
        b = _int(got[1])
        c = _int(got[2])
        if a is None or b is None or c is None:
            return False
        if [a, b, c] != runs[k]:
            return False
        leaves.append(4 * b + c)
        if c == 1:
            on_len += b
    if on_len != sum(bits):
        return False
    if _tree(leaves) != checksum:
        return False
    state = 0
    flips = 0
    H = 0
    L = 0
    seen = []
    p = 0
    for _step in range(n):
        seen.append(p)
        x = xs[p]
        if x >= hi:
            H += 1
        if x <= lo:
            L += 1
        if state == 0 and x >= hi:
            state = 1
            flips += 1
        elif state == 1 and x <= lo:
            state = 0
            flips += 1
        p = (p + stride) % n
    if len(set(seen)) != n:
        return False
    if flips != flips_c:
        return False
    if flips > H + L:
        return False
    if flips > 2 * min(H, L) + 1:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get("expected")
    if not isinstance(exp, bool):
        return False
    return _predict(case) == exp

from fractions import Fraction
from math import gcd

MAX_L = 4096


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _q(v):
    if _is_int(v):
        return Fraction(v)
    if isinstance(v, list) and len(v) == 2 and _is_int(v[0]) and _is_int(v[1]) and v[1] > 0:
        return Fraction(v[0], v[1])
    return None


def _egcd(a, b):
    x0, y0, x1, y1 = 1, 0, 0, 1
    while b != 0:
        q = a // b
        a, b = b, a - q * b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return a, x0, y0


def _merge(a, m, b, n):
    g = gcd(m, n)
    if (b - a) % g != 0:
        return None
    lcm_mn = (m // g) * n
    g2, inv, _unused = _egcd(m // g, n // g)
    if g2 != 1:
        return None
    t = (((b - a) // g) * inv) % (n // g)
    return ((a + m * t) % lcm_mn, lcm_mn)


def _crt(moduli, residues):
    big_l = 1
    prod = 1
    for m in moduli:
        big_l = (big_l // gcd(big_l, m)) * m
        prod = prod * m
        if big_l > MAX_L:
            return None
    k = len(moduli)
    rs = [residues[i] % moduli[i] for i in range(k)]
    sols = [x for x in range(big_l) if all(x % moduli[i] == rs[i] for i in range(k))]
    if len(sols) > 1:
        return None
    dec_a = len(sols) == 1
    dec_b = all((rs[i] - rs[j]) % gcd(moduli[i], moduli[j]) == 0 for i in range(k) for j in range(i + 1, k))
    acc = (rs[0], moduli[0])
    for i in range(1, k):
        if acc is None:
            break
        acc = _merge(acc[0], acc[1], rs[i], moduli[i])
    dec_c = acc is not None
    if dec_a != dec_b or dec_b != dec_c:
        return None
    coprime = all(gcd(moduli[i], moduli[j]) == 1 for i in range(k) for j in range(i + 1, k))
    single = prod == big_l
    if single != coprime:
        return None
    if not dec_a:
        return None
    if acc[1] != big_l or acc[0] != sols[0]:
        return None
    return (sols[0], big_l, single)


def _fold(xs):
    if len(xs) == 1:
        return xs[0]
    mid = len(xs) // 2
    return _fold(xs[:mid]) + 3 * _fold(xs[mid:])


def _predict(case):
    moduli = case.get('moduli')
    residues = case.get('residues')
    if not isinstance(moduli, list) or not isinstance(residues, list):
        return False
    if len(moduli) < 1 or len(moduli) != len(residues):
        return False
    if not all(_is_int(m) and m >= 1 for m in moduli):
        return False
    if not all(_is_int(r) for r in residues):
        return False
    crt = _crt(moduli, residues)
    if crt is None:
        return False
    x, n, single = crt
    claim = case.get('claim')
    if not isinstance(claim, dict):
        return False
    ts = claim.get('timestamp')
    sc = claim.get('single_cycle')
    if not _is_int(ts) or ts != x:
        return False
    if not isinstance(sc, bool) or sc != single:
        return False
    stride = case.get('stride')
    init = case.get('init')
    lo = _q(case.get('lo'))
    hi = _q(case.get('hi'))
    levels = case.get('levels')
    if not _is_int(stride) or not _is_int(init) or init not in (0, 1):
        return False
    if lo is None or hi is None or not lo < hi:
        return False
    if not isinstance(levels, list) or len(levels) != n:
        return False
    vals = [_q(v) for v in levels]
    if any(v is None for v in vals):
        return False
    s = stride % n
    if gcd(s, n) != 1:
        return False
    order = [(x + j * s) % n for j in range(n)]
    if len(set(order)) != n:
        return False
    if any(order[j + 1] != (order[j] + s) % n for j in range(n - 1)):
        return False
    stream = [vals[p] for p in order]
    st = init
    states = []
    flips = 0
    for v in stream:
        nxt = st
        if st == 0 and v >= hi:
            nxt = 1
        elif st == 1 and v <= lo:
            nxt = 0
        if nxt != st:
            flips += 1
        st = nxt
        states.append(st)
    runs = []
    start = 0
    for j in range(1, n + 1):
        if j == n or states[j] != states[start]:
            runs.append([start, j - start, states[start]])
            start = j
    nr = len(runs)
    delta = 1 if states[0] != init else 0
    if flips != nr - 1 + delta:
        return False
    hcount = sum(1 for v in stream if v >= hi)
    lcount = sum(1 for v in stream if v <= lo)
    if flips > hcount + lcount or flips > 2 * min(hcount, lcount) + 1:
        return False
    tv = Fraction(0)
    for j in range(n - 1):
        d = stream[j + 1] - stream[j]
        tv += d if d >= 0 else -d
    if (flips - 1) * (hi - lo) > tv:
        return False
    on = sum(1 for b in states if b == 1)
    if sum(r[1] for r in runs if r[2] == 1) != on or sum(r[1] for r in runs) != n:
        return False
    root = _fold([2 * r[1] + r[2] for r in runs])
    ci = claim.get('intervals')
    if not isinstance(ci, list) or len(ci) != nr:
        return False
    for j in range(nr):
        a = ci[j]
        if not isinstance(a, list) or len(a) != 3 or not all(_is_int(e) for e in a):
            return False
        if a != runs[j]:
            return False
    cf = claim.get('flips')
    con = claim.get('on_count')
    cr = claim.get('root')
    ctv = _q(claim.get('tv'))
    if not _is_int(cf) or cf != flips:
        return False
    if not _is_int(con) or con != on:
        return False
    if not _is_int(cr) or cr != root:
        return False
    if ctv is None or ctv != tv:
        return False
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get('expected')
    if not isinstance(exp, bool):
        return False
    pred = _predict(case)
    return pred == exp

from fractions import Fraction
from math import gcd

def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def _q(pair):
    if not isinstance(pair, list) or len(pair) != 2:
        return None
    a = pair[0]
    b = pair[1]
    if not _is_int(a) or not _is_int(b) or b <= 0:
        return None
    return Fraction(a, b)

def _egcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
    return old_r, old_s

def _merge(a, m, b, n):
    g, s = _egcd(m, n)
    if (b - a) % g != 0:
        return None
    t = ((b - a) // g * s) % (n // g)
    l = m // g * n
    return ((a + m * t) % l, l)

def _fold(nodes):
    k = len(nodes)
    if k == 1:
        return nodes[0]
    mid = k // 2
    return _fold(nodes[:mid]) + 3 * _fold(nodes[mid:])

def _crt(moduli, residues):
    if not isinstance(moduli, list) or not isinstance(residues, list):
        return None
    k = len(moduli)
    if k == 0 or k > 8 or k != len(residues):
        return None
    for m in moduli:
        if not _is_int(m) or m < 1:
            return None
    for r in residues:
        if not _is_int(r):
            return None
    L = 1
    prod = 1
    for m in moduli:
        L = L // gcd(L, m) * m
        prod = prod * m
        if L > 100000:
            return None
    rs = [residues[i] % moduli[i] for i in range(k)]
    sols = []
    for t in range(L):
        good = True
        for i in range(k):
            if t % moduli[i] != rs[i]:
                good = False
                break
        if good:
            sols.append(t)
            if len(sols) > 1:
                return None
    compat = True
    coprime = True
    for i in range(k):
        for j in range(i + 1, k):
            g = gcd(moduli[i], moduli[j])
            if g != 1:
                coprime = False
            if (rs[i] - rs[j]) % g != 0:
                compat = False
    cur_a = rs[0]
    cur_m = moduli[0]
    merged = True
    for i in range(1, k):
        res = _merge(cur_a, cur_m, rs[i], moduli[i])
        if res is None:
            merged = False
            break
        cur_a, cur_m = res
    if compat != (len(sols) == 1):
        return None
    if compat != merged:
        return None
    if coprime != (prod == L):
        return None
    if not compat:
        return None
    if cur_m != L or len(sols) != 1 or sols[0] != cur_a:
        return None
    return (cur_a, L, prod == L)

def _predict(case):
    if not isinstance(case, dict):
        return False
    clocks = case.get('clocks')
    if not isinstance(clocks, dict):
        return False
    crt = _crt(clocks.get('moduli'), clocks.get('residues'))
    if crt is None:
        return False
    witness, L, joint_single = crt
    claim_x = clocks.get('claim_x')
    if not _is_int(claim_x) or claim_x != witness:
        return False
    claim_sc = clocks.get('claim_single_cycle')
    if not isinstance(claim_sc, bool) or claim_sc != joint_single:
        return False
    signal = case.get('signal')
    if not isinstance(signal, list) or len(signal) != L:
        return False
    n = L
    for v in signal:
        if not _is_int(v):
            return False
    stride = case.get('stride')
    if not _is_int(stride):
        return False
    s = stride % n
    if gcd(s, n) != 1:
        return False
    order = [(k * s) % n for k in range(n)]
    if len(set(order)) != n:
        return False
    lo = _q(case.get('lo'))
    hi = _q(case.get('hi'))
    if lo is None or hi is None or not lo < hi:
        return False
    init = case.get('init')
    if not _is_int(init) or init not in (0, 1):
        return False
    stream = [Fraction(signal[p]) for p in order]
    states = []
    st = init
    flips = 0
    for v in stream:
        if st == 0:
            if v >= hi:
                st = 1
        else:
            if v <= lo:
                st = 0
        if len(states) == 0:
            if st != init:
                flips = flips + 1
        else:
            if st != states[-1]:
                flips = flips + 1
        states.append(st)
    runs = []
    start = 0
    for i in range(1, n):
        if states[i] != states[i - 1]:
            runs.append([start, i - start, states[start]])
            start = i
    runs.append([start, n - start, states[start]])
    R = len(runs)
    delta = 1 if states[0] != init else 0
    if flips != R - 1 + delta:
        return False
    H = sum(1 for v in stream if v >= hi)
    Lc = sum(1 for v in stream if v <= lo)
    if flips > H + Lc or flips > 2 * min(H, Lc) + 1:
        return False
    tv = Fraction(0)
    for i in range(1, n):
        d = stream[i] - stream[i - 1]
        tv = tv + (d if d >= 0 else -d)
    if (flips - 1) * (hi - lo) > tv:
        return False
    on_count = sum(1 for b in states if b == 1)
    on_run_sum = sum(ln for (_, ln, lb) in runs if lb == 1)
    if on_run_sum != on_count:
        return False
    leaves = [2 * ln + lb for (_, ln, lb) in runs]
    root = _fold(leaves)
    moment = Fraction(0)
    for p in range(n):
        moment = moment + (p + 1) * stream[p]
    friction = case.get('friction')
    deadband = case.get('deadband')
    if not _is_int(friction) or not _is_int(deadband):
        return False
    if friction < 1 or deadband < 1:
        return False
    gain = Fraction(deadband, deadband + friction)
    if not (0 < gain < 1):
        return False
    claim = case.get('claim')
    if not isinstance(claim, dict):
        return False
    ci = claim.get('intervals')
    if not isinstance(ci, list) or len(ci) != R:
        return False
    for it in ci:
        if not isinstance(it, list) or len(it) != 3:
            return False
        for w in it:
            if not _is_int(w):
                return False
    if ci != runs:
        return False
    cf = claim.get('flips')
    if not _is_int(cf) or cf != flips:
        return False
    co = claim.get('on_count')
    if not _is_int(co) or co != on_count:
        return False
    cr = claim.get('root')
    if not _is_int(cr) or cr != root:
        return False
    cm = _q(claim.get('moment'))
    if cm is None or cm != moment:
        return False
    cg = _q(claim.get('gain'))
    if cg is None or cg != gain:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
