        stride = case['stride']
        init = case['init']
        if not _int(stride) or not _int(init) or init not in (0, 1):
            raise ValueError
        if gcd(stride % n, n) != 1:
            raise ValueError
        lo = _q(case['lo'])
        hi = _q(case['hi'])
        friction = _q(case['friction'])
        y_prev = _q(case['y_init'])
        if not lo < hi or friction <= 0:
            raise ValueError
        gain = (hi - lo) / (hi - lo + friction)
        order = [(t * stride) % n for t in range(n)]
        ys = []
        states = []
        state = init
        for p in order:
            y = y_prev + gain * (Fraction(levels[p], 1) - y_prev)
            ys.append(y)
            y_prev = y
            if state == 0 and y >= hi:
                state = 1
            elif state == 1 and y <= lo:
                state = 0
            states.append(state)
        flips = int(states[0] != init)
        for i in range(1, n):
            flips += int(states[i] != states[i - 1])
        tv = sum((abs(ys[i] - ys[i - 1]) for i in range(1, n)), Fraction(0, 1))
        intervals = []
        start = 0
        label = states[0]
        for i in range(1, n):
            if states[i] != label:
                intervals.append([start, i - start, label])
                start = i
                label = states[i]
        intervals.append([start, n - start, label])
        on_count = sum(states)
        leaves = [2 * length + bit for start, length, bit in intervals]
        root = _tree(leaves)
        claim = case['claim']
        if not isinstance(claim, dict):
            raise ValueError
        declared_intervals = claim['intervals']
        if not isinstance(declared_intervals, list):
            raise ValueError
        for row in declared_intervals:
            if not isinstance(row, list) or len(row) != 3 or not all(_int(v) for v in row):
                raise ValueError
        declared_gain = claim['gain']
        _q(declared_gain)
        tags_well_typed = all(_int(claim[k]) for k in ('flips', 'on_count', 'checksum'))
        bound_ok = flips == 0 or (flips - 1) * (hi - lo) <= tv
        prediction = (
            tags_well_typed
            and declared_intervals == intervals
            and claim['flips'] == flips
            and claim['on_count'] == on_count
            and claim['checksum'] == root
            and declared_gain == [gain.numerator, gain.denominator]
            and bound_ok
        )
    except (KeyError, TypeError, ValueError, ZeroDivisionError, IndexError):
        prediction = False
    return prediction == expected

from fractions import Fraction
from math import gcd


def _is_int(v):
    if isinstance(v, bool):
        return False
    return isinstance(v, int)


def _as_seq(v):
    if isinstance(v, list):
        return v
    if isinstance(v, tuple):
        return list(v)
    return None


def _int_list(v):
    seq = _as_seq(v)
    if seq is None:
        return None
    out = []
    for e in seq:
        if not _is_int(e):
            return None
        out.append(e)
    return out


def _rat(v):
    seq = _as_seq(v)
    if seq is None:
        return None
    if len(seq) != 2:
        return None
    a = seq[0]
    b = seq[1]
    if not _is_int(a) or not _is_int(b):
        return None
    if b == 0:
        return None
    return Fraction(a, b)


def _egcd(a, b):
    r0 = a
    r1 = b
    s0 = 1
    s1 = 0
    t0 = 0
    t1 = 1
    while r1 != 0:
        q = r0 // r1
        nr = r0 - q * r1
        ns = s0 - q * s1
        nt = t0 - q * t1
        r0 = r1
        r1 = nr
        s0 = s1
        s1 = ns
        t0 = t1
        t1 = nt
    return r0, s0, t0


def _merge(a, m, b, n):
    got = _egcd(m, n)
    g = got[0]
    s = got[1]
    d = b - a
    if d % g != 0:
        return None
    l = m // g * n
    k = ((d // g) * s) % (n // g)
    return (a + m * k) % l, l


def _solutions_enum(moduli, residues, L):
    rr = []
    for i in range(len(moduli)):
        rr.append(residues[i] % moduli[i])
    sols = []
    for x in range(L):
        bad = False
        for i in range(len(moduli)):
            if (x - rr[i]) % moduli[i] != 0:
                bad = True
                break
        if not bad:
            sols.append(x)
    return sols


def _compatible_pairwise(moduli, residues):
    for i in range(len(moduli)):
        for j in range(i + 1, len(moduli)):
            g = gcd(moduli[i], moduli[j])
            if (residues[i] - residues[j]) % g != 0:
                return False
    return True


def _merge_fold(moduli, residues):
    x = residues[0] % moduli[0]
    m = moduli[0]
    for i in range(1, len(moduli)):
        got = _merge(x, m, residues[i] % moduli[i], moduli[i])
        if got is None:
            return None
        x = got[0]
        m = got[1]
    return x, m


def _predict(case):
    if not isinstance(case, dict):
        return False
    needed = ['moduli', 'residues', 'claim_x', 'claim_single_cycle', 'stride',
              'levels', 'lo', 'hi', 'claim_intervals', 'claim_flips',
              'claim_on_count', 'claim_root', 'tree_modulus', 'friction',
              'claim_gain']
    for k in needed:
        if k not in case:
            return False
    moduli = _int_list(case['moduli'])
    residues = _int_list(case['residues'])
    if moduli is None or residues is None:
        return False
    if len(moduli) < 1 or len(moduli) != len(residues):
        return False
    for m in moduli:
        if m < 1:
            return False
    L = 1
    for m in moduli:
        L = L // gcd(L, m) * m
    if L < 1 or L > 100000:
        return False
    prod = 1
    for m in moduli:
        prod = prod * m
    coprime_pairwise = True
    for i in range(len(moduli)):
        for j in range(i + 1, len(moduli)):
            if gcd(moduli[i], moduli[j]) != 1:
                coprime_pairwise = False
    joint_single_cycle = (prod == L)
    if joint_single_cycle != coprime_pairwise:
        return False
    sols = _solutions_enum(moduli, residues, L)
    if len(sols) > 1:
        return False
    exists_enum = (len(sols) == 1)
    pairwise = _compatible_pairwise(moduli, residues)
    folded = _merge_fold(moduli, residues)
    exists_fold = folded is not None
    if exists_enum != pairwise:
        return False
    if exists_enum != exists_fold:
        return False
    if not exists_enum:
        return False
    if folded[1] != L:
        return False
    if folded[0] != sols[0]:
        return False
    claim_x = case['claim_x']
    if not _is_int(claim_x):
        return False
    if claim_x % L != sols[0]:
        return False
    csc = case['claim_single_cycle']
    if not isinstance(csc, bool):
        return False
    if csc != joint_single_cycle:
        return False
    n = L
    stride = case['stride']
    if not _is_int(stride):
        return False
    s = stride % n
    if gcd(s, n) != 1:
        return False
    order = []
    pos = 0
    for i in range(n):
        order.append(pos)
        pos = (pos + s) % n
    if pos != 0:
        return False
    if len(set(order)) != n:
        return False
    raw_levels = _as_seq(case['levels'])
    if raw_levels is None:
        return False
    if len(raw_levels) != n:
        return False
    levels = []
    for e in raw_levels:
        q = _rat(e)
        if q is None:
            return False
        levels.append(q)
    lo = _rat(case['lo'])
    hi = _rat(case['hi'])
    if lo is None or hi is None:
        return False
    if not (lo < hi):
        return False
    band = hi - lo
    if not (band > 0):
        return False
    states = []
    st = 0
    for t in range(n):
        v = levels[order[t]]
        if st == 0:
            if v >= hi:
                st = 1
        else:
            if v <= lo:
                st = 0
        states.append(st)
    runs = []
    run_start = 0
    for t in range(1, n):
        if states[t] != states[t - 1]:
            runs.append((run_start, t - run_start, states[t - 1]))
            run_start = t
    runs.append((run_start, n - run_start, states[n - 1]))
    total = 0
    for r in runs:
        total = total + r[1]
    if total != n:
        return False
    claim_iv = _as_seq(case['claim_intervals'])
    if claim_iv is None:
        return False
    if len(claim_iv) != len(runs):
        return False
    for i in range(len(runs)):
        e = _as_seq(claim_iv[i])
        if e is None or len(e) != 3:
            return False
        for z in e:
            if not _is_int(z):
                return False
        if e[0] != runs[i][0] or e[1] != runs[i][1] or e[2] != runs[i][2]:
            return False
    delta = 0
    if states[0] == 1:
        delta = 1
    flips = len(runs) - 1 + delta
    toggles = 0
    for t in range(1, n):
        if states[t] != states[t - 1]:
            toggles = toggles + 1
    if toggles + delta != flips:
        return False
    cf = case['claim_flips']
    if not _is_int(cf):
        return False
    if cf != flips:
        return False
    on_count = 0
    for t in range(n):
        if states[t] == 1:
            on_count = on_count + 1
    on_runs = 0
    for r in runs:
        if r[2] == 1:
            on_runs = on_runs + r[1]
    if on_runs != on_count:
        return False
    co = case['claim_on_count']
    if not _is_int(co):
        return False
    if co != on_count:
        return False
    high_hits = 0
    low_hits = 0
    for v in levels:
        if v >= hi:
            high_hits = high_hits + 1
        if v <= lo:
            low_hits = low_hits + 1
    if flips > high_hits + low_hits:
        return False
    mn = high_hits
    if low_hits < mn:
        mn = low_hits
    if flips > 2 * mn + 1:
        return False
    if flips >= 1:
        tv = Fraction(0, 1)
        for t in range(1, n):
            d = levels[order[t]] - levels[order[t - 1]]
            if d < 0:
                d = -d
            tv = tv + d
        if (flips - 1) * band > tv:
            return False
    mod = case['tree_modulus']
    if not _is_int(mod):
        return False
    if mod < 2:
        return False
    nodes = []
    for r in runs:
        nodes.append(2 * r[1] + r[2])
    while len(nodes) > 1:
        nxt = []
        i = 0
        while i + 1 < len(nodes):
            nxt.append(nodes[i] + 3 * nodes[i + 1])
            i = i + 2
        if i < len(nodes):
            nxt.append(nodes[i])
        nodes = nxt
    root = nodes[0] % mod
    cr = case['claim_root']
    if not _is_int(cr):
        return False
    if cr != root:
        return False
    fr = _rat(case['friction'])
    cg = _rat(case['claim_gain'])
    if fr is None or cg is None:
        return False
    if fr < 0:
        return False
    denom = band + fr
    if not (denom > 0):
        return False
    gain = band / denom
    if not (gain > 0):
        return False
    if not (gain < 1):
        return False
    if gain != cg:
        return False
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    if 'expected' not in case:
        return False
    exp = case['expected']
    if not isinstance(exp, bool):
        return False
    got = _predict(case)
    return bool(got) == exp

from math import gcd
from fractions import Fraction
from itertools import combinations


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _to_frac(x):
    if _is_int(x):
        return Fraction(x, 1)
    if isinstance(x, list) and len(x) == 2 and _is_int(x[0]) and _is_int(x[1]) and x[1] > 0:
        return Fraction(x[0], x[1])
    return None


def _ext_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return old_r, old_s, old_t


def _crt_merge(a, m, b, n):
    g, s, t = _ext_gcd(m, n)
    if (b - a) % g != 0:
        return None
    lcm = m // g * n
    diff = (b - a) // g
    x = (a + m * ((s * diff) % (n // g))) % lcm
    return x, lcm


def _lcm_all(moduli):
    out = 1
    for m in moduli:
        out = out // gcd(out, m) * m
    return out


def _enum_decider(moduli, rems, L):
    cnt = 0
    sol = None
    for x in range(L):
        ok = True
        for i in range(len(moduli)):
            if x % moduli[i] != rems[i] % moduli[i]:
                ok = False
                break
        if ok:
            cnt += 1
            sol = x
            if cnt > 1:
                break
    return cnt, sol


def _pairwise_decider(moduli, rems):
    for i, j in combinations(range(len(moduli)), 2):
        if (rems[i] - rems[j]) % gcd(moduli[i], moduli[j]) != 0:
            return False
    return True


def _merge_decider(moduli, rems):
    a = rems[0] % moduli[0]
    m = moduli[0]
    for i in range(1, len(moduli)):
        res = _crt_merge(a, m, rems[i] % moduli[i], moduli[i])
        if res is None:
            return None
        a, m = res
    return a, m


def _tree_fold(leaves):
    if len(leaves) == 1:
        return leaves[0]
    half = len(leaves) // 2
    left = _tree_fold(leaves[:half])
    right = _tree_fold(leaves[half:])
    return left + 3 * right


def _hysteresis(stream, lo, hi, init):
    st = init
    out = []
    for v in stream:
        if st == 0 and v >= hi:
            st = 1
        elif st == 1 and v <= lo:
            st = 0
        out.append(st)
    return out


def _max_runs(states):
    runs = []
    start = 0
    for i in range(1, len(states) + 1):
        if i == len(states) or states[i] != states[start]:
            runs.append([start, i - start, states[start]])
            start = i
    return runs


def _total_variation(stream):
    total = Fraction(0, 1)
    for i in range(1, len(stream)):
        total += abs(stream[i] - stream[i - 1])
    return total


def _predict(case):
    if not isinstance(case, dict):
        return False
    moduli = case.get('moduli')
    rems = case.get('remainders')
    if not isinstance(moduli, list) or not isinstance(rems, list):
        return False
    if len(moduli) < 1 or len(moduli) != len(rems):
        return False
    for m in moduli:
        if not _is_int(m) or m < 1:
            return False
    for r in rems:
        if not _is_int(r):
            return False
    claim_x = case.get('claim_x')
    claim_single = case.get('claim_single_cycle')
    if not _is_int(claim_x) or not isinstance(claim_single, bool):
        return False
    L = _lcm_all(moduli)
    if L > 100000:
        return False
    cnt, sol = _enum_decider(moduli, rems, L)
    pair = _pairwise_decider(moduli, rems)
    merged = _merge_decider(moduli, rems)
    solvable = pair
    if (cnt == 1) != solvable:
        return False
    if solvable != (merged is not None):
        return False
    if not solvable:
        return False
    if merged[1] != L or sol != merged[0] or cnt != 1:
        return False
    if claim_x % L != merged[0]:
        return False
    prod = 1
    for m in moduli:
        prod *= m
    if claim_single != (prod == L):
        return False
    n = case.get('n')
    if not _is_int(n) or n != L:
        return False
    stride = case.get('stride')
    if not _is_int(stride) or gcd(stride % n, n) != 1:
        return False
    levels_raw = case.get('levels')
    if not isinstance(levels_raw, list) or len(levels_raw) != n:
        return False
    levels = []
    for v in levels_raw:
        f = _to_frac(v)
        if f is None:
            return False
        levels.append(f)
    lo = _to_frac(case.get('lo'))
    hi = _to_frac(case.get('hi'))
    if lo is None or hi is None or not lo < hi:
        return False
    init = case.get('init')
    if not _is_int(init) or init not in (0, 1):
        return False
    stream = []
    for t in range(n):
        stream.append(levels[(t * stride) % n])
    states = _hysteresis(stream, lo, hi, init)
    runs = _max_runs(states)
    flips = len(runs) - 1 + (1 if states[0] == 1 else 0)
    on_count = 0
    for st in states:
        if st == 1:
            on_count += 1
    on_run_sum = 0
    for r in runs:
        if r[2] == 1:
            on_run_sum += r[1]
    if on_count != on_run_sum:
        return False
    leaves = []
    for r in runs:
        leaves.append(2 * r[1] + r[2])
    root = _tree_fold(leaves)
    tv = _total_variation(stream)
    if flips >= 1 and Fraction(flips - 1, 1) * (hi - lo) > tv:
        return False
    intervals = case.get('intervals')
    if not isinstance(intervals, list) or len(intervals) != len(runs):
        return False
    for i in range(len(intervals)):
        iv = intervals[i]
        if not isinstance(iv, list) or len(iv) != 3:
            return False
        if not _is_int(iv[0]) or not _is_int(iv[1]) or not _is_int(iv[2]):
            return False
        if iv[2] not in (0, 1) or iv != runs[i]:
            return False
    cf = case.get('flips')
    if not _is_int(cf) or cf != flips:
        return False
    co = case.get('on_count')
    if not _is_int(co) or co != on_count:
        return False
    cr = case.get('root')
    if not _is_int(cr) or cr != root:
        return False
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    expected = case.get('expected')
    if not isinstance(expected, bool):
        return False
    return _predict(case) == expected

from fractions import Fraction
from math import gcd

def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def _q(v):
    if not isinstance(v, list) or len(v) != 2:
        return None
    if not _is_int(v[0]) or not _is_int(v[1]) or v[1] <= 0:
        return None
    return Fraction(v[0], v[1])

def _egcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return old_r, old_s, old_t

def _merge(ms, rs):
    a = 0
    m = 1
    for i in range(len(ms)):
        n = ms[i]
        b = rs[i] % n
        g, u, v = _egcd(m, n)
        d = b - a
        if d % g != 0:
            return None
        w = n // g
        step = ((d // g) * u) % w
        a = (a + m * step) % (m * w)
        m = m * w
    return [a, m]

def _sum_tree(values):
    if len(values) == 1:
        return values[0]
    mid = (len(values) + 1) // 2
    return _sum_tree(values[:mid]) + _sum_tree(values[mid:])

def _chiral_tree(values, modulus):
    if len(values) == 1:
        return values[0] % modulus
    mid = (len(values) + 1) // 2
    left = _chiral_tree(values[:mid], modulus)
    right = _chiral_tree(values[mid:], modulus)
    return (left + 3 * right) % modulus

def _prediction(case):
    ms = case.get('moduli')
    rs = case.get('residues')
    if not isinstance(ms, list) or not isinstance(rs, list):
        return False
    if len(ms) == 0 or len(ms) != len(rs):
        return False
    for m in ms:
        if not _is_int(m) or m <= 0:
            return False
    for r in rs:
        if not _is_int(r):
            return False
    nr = [rs[i] % ms[i] for i in range(len(ms))]
    lcm = 1
    product = 1
    for m in ms:
        lcm = lcm * m // gcd(lcm, m)
        product = product * m
        if lcm > 100000:
            return False
    compatible = True
    for i in range(len(ms)):
        for j in range(i + 1, len(ms)):
            if (nr[i] - nr[j]) % gcd(ms[i], ms[j]) != 0:
                compatible = False
    if not compatible:
        return False
    merged = _merge(ms, nr)
    if merged is None or merged[1] != lcm:
        return False
    count = 0
    witness = None
    for x in range(lcm):
        good = True
        for i in range(len(ms)):
            if x % ms[i] != nr[i]:
                good = False
                break
        if good:
            count = count + 1
            witness = x
            if count > 1:
                return False
    if count != 1 or witness != merged[0]:
        return False
    solution = case.get('solution')
    if not _is_int(solution) or solution != witness:
        return False
    clock_flag = case.get('clock_single_cycle')
    if not isinstance(clock_flag, bool):
        return False
    if clock_flag != (product == lcm):
        return False
    n = lcm
    levels = case.get('levels')
    if not isinstance(levels, list) or len(levels) != n:
        return False
    lo = _q(case.get('lo'))
    hi = _q(case.get('hi'))
    if lo is None or hi is None or lo >= hi:
        return False
    stride = case.get('stride')
    init = case.get('init')
    if not _is_int(stride) or gcd(stride, n) != 1:
        return False
    if not _is_int(init) or init not in [0, 1]:
        return False
    values = []
    for item in levels:
        value = _q(item)
        if value is None:
            return False
        values.append(value)
    positions = [(witness + t * stride) % n for t in range(n)]
    if sorted(positions) != list(range(n)):
        return False
    stream = [values[p] for p in positions]
    state = init
    states = []
    flips = 0
    high_count = 0
    low_count = 0
    for value in stream:
        if value >= hi:
            high_count = high_count + 1
        if value <= lo:
            low_count = low_count + 1
        next_state = state
        if state == 0 and value >= hi:
            next_state = 1
        elif state == 1 and value <= lo:
            next_state = 0
        if next_state != state:
            flips = flips + 1
        state = next_state
        states.append(state)
    runs = []
    start = 0
    for i in range(1, n + 1):
        if i == n or states[i] != states[start]:
            runs.append([start, i - start, states[start]])
            start = i
    claimed = case.get('claim')
    if not isinstance(claimed, dict):
        return False
    if claimed.get('intervals') != runs:
        return False
    max_intervals = case.get('max_intervals')
    if not _is_int(max_intervals) or max_intervals < len(runs):
        return False
    if not _is_int(claimed.get('flips')) or claimed.get('flips') != flips:
        return False
    on_count = 0
    for run in runs:
        if run[2] == 1:
            on_count = on_count + run[1]
    if not _is_int(claimed.get('on_count')) or claimed.get('on_count') != on_count:
        return False
    delta = 1 if states[0] != init else 0
    if flips != len(runs) - 1 + delta:
        return False
    if flips > high_count + low_count:
        return False
    if flips > 2 * min(high_count, low_count) + 1:
        return False
    tv = Fraction(0, 1)
    for i in range(1, n):
        tv = tv + abs(stream[i] - stream[i - 1])
    if flips >= 1 and (flips - 1) * (hi - lo) > tv:
        return False
    if _sum_tree([run[1] for run in runs]) != n:
        return False
    modulus = case.get('checksum_modulus')
    if not _is_int(modulus) or modulus < 2:
        return False
    root = claimed.get('root')
    if not _is_int(root) or root < 0 or root >= modulus:
        return False
    leaves = [2 * run[1] + run[2] for run in runs]
    if root != _chiral_tree(leaves, modulus):
        return False
    moment = Fraction(0, 1)
    for p in range(n):
        moment = moment + (p + 1) * values[p]
    claimed_moment = _q(claimed.get('moment'))
    if claimed_moment is None or claimed_moment != moment:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    expected = case.get('expected')
    if not isinstance(expected, bool):
        return False
    prediction = _prediction(case)
    return isinstance(prediction, bool) and prediction == expected

from math import gcd
from fractions import Fraction

def _int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _q(x):
    if _int(x):
        return Fraction(x, 1)
    if isinstance(x, list) and len(x) == 2 and _int(x[0]) and _int(x[1]) and x[1] > 0:
        return Fraction(x[0], x[1])
    return None

def _fold(leaves):
    m = len(leaves)
    if m == 1:
        return leaves[0]
    mid = m // 2
    return _fold(leaves[:mid]) + 3 * _fold(leaves[mid:])

def _pred(case):
    if not isinstance(case, dict):
        return False
    n = case.get("n")
    stride = case.get("stride")
    if not _int(n) or n < 1 or not _int(stride):
        return False
    step = stride % n
    if gcd(step, n) != 1:
        return False
    lo = _q(case.get("lo"))
    hi = _q(case.get("hi"))
    if lo is None or hi is None or not (lo < hi):
        return False
    raw = case.get("levels")
    if not isinstance(raw, list) or len(raw) != n:
        return False
    xs = []
    for item in raw:
        q = _q(item)
        if q is None:
            return False
        xs.append(q)
    if "init" in case:
        init = case.get("init")
        if not _int(init) or (init != 0 and init != 1):
            return False
    else:
        init = 0
    order = []
    seen = []
    p = 0
    k = 0
    while k < n:
        if p in seen:
            return False
        seen.append(p)
        order.append(p)
        p = (p + step) % n
        k += 1
    if len(seen) != n or p != 0:
        return False
    state = init
    states = []
    flips = 0
    for idx in order:
        v = xs[idx]
        nxt = state
        if state == 0 and v >= hi:
            nxt = 1
        elif state == 1 and v <= lo:
            nxt = 0
        if nxt != state:
            flips += 1
        state = nxt
        states.append(state)
    runs = []
    s = 0
    i = 1
    while i <= n:
        if i == n or states[i] != states[s]:
            runs.append([s, i - s, states[s]])
            s = i
        i += 1
    R = len(runs)
    delta = 0
    if states[0] != init:
        delta = 1
    if flips != R - 1 + delta:
        return False
    H = 0
    L = 0
    for v in xs:
        if v >= hi:
            H += 1
        if v <= lo:
            L += 1
    small = H
    if L < H:
        small = L
    if flips > H + L or flips > 2 * small + 1:
        return False
    tv = Fraction(0, 1)
    j = 0
    while j + 1 < n:
        d = xs[order[j + 1]] - xs[order[j]]
        if d < 0:
            d = -d
        tv += d
        j += 1
    if (flips - 1) * (hi - lo) > tv:
        return False
    leaves = []
    on_len = 0
    covered = 0
    prev = -1
    for run in runs:
        if not isinstance(run, list) or len(run) != 3:
            return False
        start, length, label = run[0], run[1], run[2]
        if not _int(start) or not _int(length) or not _int(label):
            return False
        if length < 1 or (label != 0 and label != 1):
            return False
        if prev == label:
            return False
        prev = label
        leaves.append(2 * length + label)
        covered += length
        if label == 1:
            on_len += length
    if covered != n or len(leaves) == 0:
        return False
    checksum = _fold(leaves)
    on = 0
    for bit in states:
        on += bit
    if on_len != on:
        return False
    claim = case.get("claim")
    if not isinstance(claim, dict):
        return False
    if claim.get("intervals") != runs:
        return False
    if claim.get("flips") != flips:
        return False
    if claim.get("checksum") != checksum:
        return False
    if claim.get("on") != on:
        return False
    mom = Fraction(0, 1)
    p = 0
    while p < n:
        mom += Fraction(p + 1, 1) * xs[p]
        p += 1
    want = claim.get("moment")
    if not (isinstance(want, list) and len(want) == 2 and _int(want[0]) and _int(want[1]) and want[1] > 0):
        return False
    if want[0] != mom.numerator or want[1] != mom.denominator:
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get("expected")
    if not isinstance(exp, bool):
        return False
    return _pred(case) == exp
